import hashlib

def shingles(text, k=5):
    w = text.split()
    if len(w) < k:
        return set([" ".join(w)])
    return set(" ".join(w[i:i+k]) for i in range(len(w)-k+1))

def minhash(s, n=64):
    sig = []
    for seed in range(n):
        m = min(int(hashlib.md5(f"{seed}:{x}".encode()).hexdigest()[:8], 16) for x in s)
        sig.append(m)
    return sig

